UPDATE studyroom_generation_jobs
SET status='RUNNING',lease_token=#{leaseToken},lease_until=#{leaseUntil},heartbeat_at=#{heartbeatAt},updated_at=#{updatedAt}
WHERE id=#{jobId} AND status='QUEUED' AND next_attempt_at<=CURRENT_TIMESTAMP

UPDATE studyroom_generation_jobs
SET status='FAILED',failure_code=#{failureCode},failure_message=#{failureMessage},updated_at=CURRENT_TIMESTAMP
WHERE id=#{jobId} AND lease_token=#{leaseToken}

UPDATE study_outline_drafts
SET depth=#{depth},status=#{status},pending_job_id=NULL,updated_at=CURRENT_TIMESTAMP
WHERE id=#{draftId} AND pending_job_id=#{jobId}
